import os,json,re
d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n')
G={}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
    k,h,w=m[1],int(m[2]),int(m[3])
    rows=[r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
        G[k]=[[int(x) for x in r] for r in rows]

def transform(g):
    h,w=len(g),len(g[0])
    def groups(axis):
        n=h if axis==0 else w
        out=[];cur=[]
        for i in range(n):
            sep=all(g[i][c]==8 for c in range(w)) if axis==0 else all(g[r][i]==8 for r in range(h))
            if sep:
                if cur: out.append(cur);cur=[]
            else: cur.append(i)
        if cur: out.append(cur)
        if not out: return []
        L=len(out[0]);return [gr for gr in out if len(gr)==L]
    RG,CG=groups(0),groups(1)
    # locate markers by cell indices
    marks={2:[],3:[]}
    for ri,rgr in enumerate(RG):
        for ci,cgr in enumerate(CG):
            for r in rgr:
                for c in cgr:
                    if g[r][c] in (2,3): marks[g[r][c]].append((ri,ci))
    fills=[]  # (color, axis, fixed, lo, hi) axis0=row span, axis1=col span
    for col,ms in marks.items():
        for axis in (0,1):
            d={}
            for m in ms: d.setdefault(m[axis],[]).append(m[1-axis])
            for fixed,vals in d.items():
                if len(vals)>=2:
                    fills.append((col,axis,fixed,min(vals),max(vals)))
    out=[row[:] for row in g]
    for ri,rgr in enumerate(RG):
        for ci,cgr in enumerate(CG):
            cols=set()
            for col,axis,fixed,lo,hi in fills:
                idx,fix=(ri,ci) if axis==0 else (ci,ri)
                if fix==fixed and lo<=idx<=hi: cols.add(col)
            if cols:
                val=6 if cols=={2,3} else (2 if 2 in cols else 3)
                for r in rgr:
                    for c in cgr: out[r][c]=val
    return out

